const PuzzleCore=typeof module!=='undefined'?require('./games/core.js'):window.GameCore;
'use strict';
const THEMES = {
 harvest: { name: 'Golden hour', note: 'Warm, bright & a little autumnal', emoji: '✳', accent: '#ad572f', dark: '#334b35', bg: '#fff9ee', light: '#eee6cf', headline: 'A bumper crop\nof good news.', kicker: 'THIS WEEK, WE GREW SOMETHING GREAT', intro: 'Big moves, small victories, and the people behind them. Here’s a little look at what we made happen together this week.', closing: 'Here’s to the people who make the good things happen. Same time next week?' },
 cosmic: { name: 'Out of this world', note: 'For a week of stellar work', emoji: '🚀', accent: '#7561b4', dark: '#29284b', bg: '#f7f4ff', light: '#e7e1f5', headline: 'One team.\nStellar things.', kicker: 'GOOD NEWS FROM OUR LITTLE UNIVERSE', intro: 'A whole constellation of wins, powered by our people. Here’s what took off across the company this week.', closing: 'Thanks for taking us a little further this week. Onward and upward!' },
 confetti: { name: 'Cue the confetti', note: 'Big celebration energy', emoji: '🎉', accent: '#c54d6a', dark: '#493749', bg: '#fff7f8', light: '#f4dfE6', headline: 'Good work.\nGreat people.', kicker: 'YOUR WEEKLY DOSE OF TEAM MAGIC', intro: 'Consider this your invitation to celebrate. These are the wins that deserve a little extra applause this week.', closing: 'A round of applause for everyone who made this week happen. Keep the good going!' },
 cozy: { name: 'The good news club', note: 'A cozy little catch-up', emoji: '☕', accent: '#916b45', dark: '#414b3e', bg: '#faf8f0', light: '#eae8d8', headline: 'Pour a cup.\nCatch the good.', kicker: 'FRESHLY BREWED TEAM WINS', intro: 'Settle in for a few good things from around the company. A little progress, a little gratitude, and plenty to be proud of.', closing: 'Thanks for all the care you put into your work. Enjoy a well-earned breather.' }
};
const KEY = 'weekly-wins-studio-v1';
function escapeHTML(value) { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function richText(value) { return escapeHTML(value).replace(/\n/g, '<br>'); }
function safeURL(value) { try { const u = new URL(value); return u.protocol === 'https:' ? u.href : ''; } catch { return ''; } }
function localDate() { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function dateLabel(value) { const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(value || ''); if(!match) return 'This week'; const d=new Date(Number(match[1]),Number(match[2])-1,Number(match[3])); return d.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}); }
function newDraft(sample=false) { const t=THEMES.harvest; return { company:'Concept3D', date:localDate(), subject:'This week’s wins ✳ A little good news from around the team', intro:t.intro, theme:'harvest', headline:t.headline, closing:t.closing, image:'', imageAlt:'A celebration of our team’s wins', fact:'', factSource:'', question:'', answer:'', showAnswer:false, teamRiddles:[], sample, wins:sample ? [{sample:true,team:'Engineering',title:'A smoother experience, shipped.',body:'The team shipped improvements that make getting around a campus map feel even more effortless. A big thank-you to everyone who tested, refined, and brought it over the finish line.'},{sample:true,team:'Customer Success',title:'Turning feedback into forward motion.',body:'The team helped a customer bring their next big idea to life. Thoughtful collaboration, a happy partner, and a reminder of why we do what we do.'},{sample:true,team:'Sales & Marketing',title:'New conversations. New possibilities.',body:'A week of great conversations and meaningful connections. Cheers to the team putting our story out into the world.'}] : [] }; }
function normalizeDraft(s) { if(!s || typeof s !== 'object' || !Array.isArray(s.wins)) throw new Error('Invalid draft'); const out=newDraft(); for(const k of ['company','date','subject','intro','headline','closing','image','imageAlt','fact','factSource','question','answer']) if(typeof s[k]==='string') out[k]=s[k].slice(0,20000); out.customTheme=normalizeCustomTheme(s.customTheme);out.theme=s.theme==='custom'&&out.customTheme?'custom':THEMES[s.theme]?s.theme:'harvest'; out.teamRiddles=normalizeTeamRiddles(s.teamRiddles);out.showAnswer=s.showAnswer===true; out.sample=s.sample===true; out.wins=s.wins.slice(0,200).filter(w=>w&&typeof w==='object').map(w=>({sample:w.sample===true||(s.sample===true&&w.sample===undefined),team:String(w.team||'Team').slice(0,200),title:String(w.title||'').slice(0,1000),body:String(w.body||'').slice(0,20000),image:String(w.image||'').slice(0,4000),imageAlt:String(w.imageAlt||'').slice(0,1000),imageCaption:String(w.imageCaption||'').slice(0,1000),media:normalizeMedia(w)})); out.gameThemes=normalizeGameThemes(s.gameThemes);out.games=normalizeGames(s.games);out.gamesURL=typeof s.gamesURL==='string'?safeGameURL(s.gamesURL):'';return out; }
function normalizeCustomTheme(value) {
 if(!value||typeof value!=='object')return null;
 const out={};for(const key of ['name','note','emoji','headline','kicker','intro','closing']){if(typeof value[key]!=='string'||!value[key].trim()||value[key].length>2000)return null;out[key]=value[key];}
 for(const key of ['accent','dark','bg','light']){if(typeof value[key]!=='string'||!/^#[0-9a-fA-F]{6}$/.test(value[key]))return null;out[key]=value[key];}
 return out;
}
function getTheme(s){return s.theme==='custom'?(normalizeCustomTheme(s.customTheme)||THEMES.harvest):(THEMES[s.theme]||THEMES.harvest);}
const MAX_MEDIA=12, MAX_UPLOAD_BYTES=2*1024*1024;
function mediaSource(value){if(typeof value!=='string')return '';return safeURL(value)||(/^data:image\/(?:png|jpeg|gif|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(value)&&value.length<=MAX_UPLOAD_BYTES*1.4?value:'');}
function normalizeMedia(w){const items=Array.isArray(w.media)?w.media:w.image?[{src:w.image,alt:w.imageAlt,caption:w.imageCaption}]:[];return items.slice(0,MAX_MEDIA).filter(m=>m&&mediaSource(m.src)).map(m=>({src:mediaSource(m.src),alt:String(m.alt||'').slice(0,1000),caption:String(m.caption||'').slice(0,1000),name:String(m.name||'image').slice(0,200),info:String(m.info||'').slice(0,200)}));}
function hasWinContent(w){return !!(w.title.trim()||w.body.trim()||normalizeMedia(w).length);}
function groupWins(s){const groups=new Map();for(const w of s.wins){if(!hasWinContent(w))continue;const team=w.team.trim()||'Team';if(!groups.has(team))groups.set(team,[]);groups.get(team).push(w);}return groups;}
function winImageHTML(w,forGmail=false){return normalizeMedia(w).map(m=>forGmail&&m.src.startsWith('data:')?`<p style="font:italic 12px Arial,sans-serif;color:#6c7364">[Insert image: ${escapeHTML(m.alt||m.name)}]</p>${m.caption?`<p style="font:italic 12px Arial,sans-serif;color:#6c7364">${richText(m.caption)}</p>`:''}`:`<div style="margin:16px 0 20px"><img src="${escapeHTML(m.src)}" alt="${escapeHTML(m.alt||`${w.team||'Team'} win image`)}" width="536" style="display:block;width:100%;max-width:536px;height:auto;border:0;border-radius:8px">${m.caption?`<p style="font:italic 12px/1.6 Arial,sans-serif;color:#6c7364;margin:8px 0 0">${richText(m.caption)}</p>`:''}</div>`).join('');}
function detectImageType(bytes){const b=Array.from(bytes);if(b.slice(0,8).join(',')==='137,80,78,71,13,10,26,10')return 'image/png';if(b[0]===255&&b[1]===216&&b[2]===255)return 'image/jpeg';const t=String.fromCharCode(...b.slice(0,12));if(/^GIF8[79]a/.test(t))return 'image/gif';if(t.startsWith('RIFF')&&t.slice(8,12)==='WEBP')return 'image/webp';return '';}
function imageDimensions(width,height){const scale=Math.min(1,1072/width,1600/height);return {width:Math.max(1,Math.round(width*scale)),height:Math.max(1,Math.round(height*scale))};}
function vibeDraft(s){const {games,gamesURL,gameThemes,...source}=s;return {...source,wins:s.wins.map(w=>({team:w.team,title:w.title,body:w.body,sample:w.sample,hasImage:normalizeMedia(w).length>0,imageAlt:normalizeMedia(w).map(m=>m.alt).join('; ').slice(0,1000)}))};}
function normalizeTeamRiddles(value){if(!Array.isArray(value))return [];const seen=new Set();return value.slice(0,100).filter(r=>r&&typeof r.team==='string'&&typeof r.question==='string'&&typeof r.answer==='string').map(r=>({team:r.team.trim().slice(0,200),question:r.question.slice(0,1000),answer:r.answer.slice(0,500),kind:r.kind==='trivia'?'trivia':'riddle'})).filter(r=>r.team&&!seen.has(r.team)&&seen.add(r.team));}
function activeRiddles(s){const teams=groupWins(s);return normalizeTeamRiddles(s.teamRiddles).filter(r=>teams.has(r.team)&&r.question.trim());}
function applyVibeResult(draft,result,includeRiddle=false,includeTrivia=false){
 if(includeRiddle&&includeTrivia)throw new Error('Choose either riddles or trivia.');
 const theme=normalizeCustomTheme(result.theme);if(!theme)throw new Error('The generated theme could not be read.');
 const out=normalizeDraft(draft);out.customTheme=theme;out.theme='custom';
 for(const key of ['headline','intro','closing'])out[key]=theme[key];
 if(typeof result.subject!=='string'||!result.subject.trim())throw new Error('The generated subject could not be read.');out.subject=result.subject.slice(0,250);
 if(!Array.isArray(result.winHeadlines))throw new Error('The generated headlines could not be read.');
 const expected=new Set(out.wins.map((w,i)=>hasWinContent(w)?i:null).filter(i=>i!==null));
 for(const item of result.winHeadlines){if(!Number.isInteger(item.index)||!expected.delete(item.index)||typeof item.title!=='string'||!item.title.trim())throw new Error('The generated headlines did not match your wins.');out.wins[item.index].title=item.title.slice(0,200);}
 if(expected.size)throw new Error('The generated headlines did not match your wins.');
 if(includeRiddle||includeTrivia){
  const teams=new Set(groupWins(out).keys());
  if(!Array.isArray(result.teamRiddles)||result.teamRiddles.length!==teams.size)throw new Error('The generated questions did not match your teams.');
  out.teamRiddles=result.teamRiddles.map(r=>{if(!r||typeof r.team!=='string'||!teams.delete(r.team)||typeof r.question!=='string'||!r.question.trim()||typeof r.answer!=='string'||!r.answer.trim())throw new Error('The generated questions did not match your teams.');return {team:r.team,question:r.question.slice(0,1000),answer:r.answer.slice(0,500),kind:includeTrivia?'trivia':'riddle'};});
  out.question='';out.answer='';
 }
 return out;
}
function parseWins(raw) { let team='Team'; const wins=[]; for(let line of raw.split(/\r?\n/)){ line=line.trim().replace(/^[-*•]\s*/, ''); if(!line) continue; const heading=/^(.{1,80}):\s*$/.exec(line); if(heading){team=heading[1];continue;} const inline=/^([^:]{1,80}):\s+(.+)$/.exec(line); if(inline){team=inline[1];line=inline[2];} wins.push({team,title:'',body:line}); } return wins; }
function normalizeGameThemes(value){return {word:typeof value?.word==='string'?value.word.slice(0,300):'',connections:Array.from({length:4},(_,i)=>typeof value?.connections?.[i]==='string'?value.connections[i].slice(0,300):'')};}
function normalizeGames(value){try{return PuzzleCore.validatePuzzle(value);}catch{return null;}}
function safeGameURL(value){try{const u=new URL(value);if(u.username||u.password)return '';if(u.protocol==='https:')return u.href;if(u.protocol==='http:'&&!u.port&&/^[a-z0-9][a-z0-9.-]*\.s3-website[.-][a-z]{2}(?:-[a-z]+)+-\d\.amazonaws\.com(?:\.cn)?$/.test(u.hostname))return u.href;return '';}catch{return '';}}
function gamesLink(s){const games=normalizeGames(s.games),base=safeGameURL(s.gamesURL);if(!games||!base)return '';const url=new URL(base);url.hash='';url.searchParams.set('edition',games.id);return url.href;}
function gameEmailHTML(s,t,forGmail){const game=normalizeGames(s.games);if(!game)return '';const link=gamesLink(s);if(forGmail&&!link)return '';return `<tr><td style="padding:26px 32px 0"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border:1px solid ${t.light};border-radius:8px"><tr><td style="padding:22px"><p style="font:700 10px Arial,sans-serif;letter-spacing:1.3px;color:${t.accent};margin:0 0 12px">THE WEEKLY BRAIN BREAK</p><h2 style="font:normal 24px Georgia,serif;color:${t.dark};margin:0 0 14px">${escapeHTML(game.title)}</h2><p style="font:700 20px Arial,sans-serif;letter-spacing:6px;color:${t.dark};margin:0 0 14px">□ □ □ □ □ &nbsp; 🟨 🟩 🟦 🟪</p><p style="font:13px/1.7 Arial,sans-serif;color:#535b50;margin:0 0 18px">Guess a five-letter word in six tries. Then find four hidden groups in sixteen words.</p>${link?`<a href="${escapeHTML(link)}" style="display:inline-block;background:${t.dark};color:#ffffff;text-decoration:none;font:700 12px Arial,sans-serif;padding:13px 17px;border-radius:5px">Play this week’s games ↗</a>`:'<p style="font:12px Arial,sans-serif;color:#7c8072;margin:0">Preview only. Add the published game URL in The extras to include this in your Gmail copy.</p>'}</td></tr></table></td></tr>`;}
function emailHTML(s,forGmail=false) {
 const t=getTheme(s), groups=groupWins(s),riddles=activeRiddles(s);
 const riddleHTML=team=>{const r=riddles.find(r=>r.team===team);return r?`<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:${t.light};border-radius:8px;margin:18px 0 0"><tr><td style="padding:18px"><p style="font:700 10px Arial,sans-serif;letter-spacing:1.2px;color:${t.accent};margin:0 0 8px">✦ ${escapeHTML(team.toUpperCase())} ${r.kind==='trivia'?'TRIVIA':'BRAIN TEASER'}</p><p style="font:normal 19px/1.5 Georgia,serif;color:${t.dark};margin:0">${richText(r.question)}</p><p style="font:10px Arial,sans-serif;color:#6c7364;margin:10px 0 0">${s.showAnswer?'Answer at the end of this email.':'Got a guess? Share it with your team.'}</p></td></tr></table>`:'';};
 const sections=[...groups].map(([team,wins],i)=>`<tr><td style="padding:24px 32px 0"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-top:1px solid ${t.light}"><tr><td style="padding-top:20px"><p style="margin:0 0 10px;color:${t.accent};font:700 10px Arial,sans-serif;letter-spacing:1.5px">${String(i+1).padStart(2,'0')} &nbsp; ${escapeHTML(team.toUpperCase())}</p>${wins.map(w=>`${w.title?`<h2 style="margin:8px 0 10px;font:normal 24px Georgia,serif;color:${t.dark}">${richText(w.title)}</h2>`:''}${w.body?`<p style="font:14px/1.8 Arial,sans-serif;margin:0 0 15px;color:#535b50">${richText(w.body)}</p>`:''}${winImageHTML(w,forGmail)}`).join('')}${riddleHTML(team)}</td></tr></table></td></tr>`).join('');
 const image=safeURL(s.image),source=safeURL(s.factSource);
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHTML(s.subject)}</title></head><body style="margin:0;padding:0;background:${t.bg}"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:${t.bg}"><tr><td align="center"><table role="presentation" width="600" cellspacing="0" cellpadding="0" style="width:100%;max-width:600px;background:${t.bg}"><tr><td style="padding:27px 32px 0"><table role="presentation" width="100%"><tr><td style="font:700 11px Arial,sans-serif;letter-spacing:2px;color:${t.dark}">${escapeHTML(s.company||'OUR TEAM')} <span style="color:${t.accent}"> / </span> WEEKLY WINS</td><td align="right" style="font:10px Arial,sans-serif;color:#7c8072">${escapeHTML(dateLabel(s.date))}</td></tr></table></td></tr><tr><td style="padding:34px 32px 0"><div style="font:10px Arial,sans-serif;letter-spacing:1.5px;color:${t.accent};font-weight:bold">${escapeHTML(t.kicker)}</div><table role="presentation" width="100%"><tr><td style="padding-top:15px"><h1 style="font:normal 46px/1.06 Georgia,serif;letter-spacing:-1.5px;color:${t.dark};margin:0">${richText(s.headline)}</h1></td><td align="right" style="font:normal 65px Georgia,serif;color:${t.accent};padding-left:8px">${escapeHTML(t.emoji)}</td></tr></table><p style="font:14px/1.8 Arial,sans-serif;color:#6c7364;margin:20px 0 0">${richText(s.intro)}</p></td></tr>${image?`<tr><td style="padding:24px 32px 0"><img src="${escapeHTML(image)}" alt="${escapeHTML(s.imageAlt||'Team celebration')}" width="536" style="display:block;width:100%;max-width:536px;height:auto;border-radius:8px"></td></tr>`:''}${sections||'<tr><td style="padding:32px;color:#7c8072;font:14px Arial,sans-serif">Add your team’s wins to see them here.</td></tr>'}${s.fact.trim()?`<tr><td style="padding:22px 32px 0"><table role="presentation" width="100%" style="background:${t.light};border-radius:8px"><tr><td style="padding:20px"><p style="margin:0 0 9px;font:700 10px Arial,sans-serif;letter-spacing:1.4px;color:${t.dark}">✦ A LITTLE SOMETHING TO KNOW</p><p style="margin:0;font:14px/1.7 Arial,sans-serif;color:#535b50">${richText(s.fact)}</p>${source?`<p style="margin:10px 0 0;font:11px Arial,sans-serif"><a href="${escapeHTML(source)}" style="color:${t.accent}">Fact source ↗</a></p>`:''}</td></tr></table></td></tr>`:''}${s.question.trim()?`<tr><td style="padding:24px 32px 0"><p style="font:700 10px Arial,sans-serif;letter-spacing:1.5px;color:${t.accent};margin:0 0 10px">THE WEEKLY BRAIN TEASER</p><p style="font:normal 21px/1.4 Georgia,serif;color:${t.dark};margin:0">${richText(s.question)}</p></td></tr>`:''}${gameEmailHTML(s,t,forGmail)}<tr><td style="padding:30px 32px"><table role="presentation" width="100%" style="border-top:1px solid ${t.light}"><tr><td style="padding-top:23px"><p style="font:italic 19px/1.5 Georgia,serif;color:${t.dark};margin:0">${richText(s.closing)}</p>${s.showAnswer&&riddles.length?`<div style="margin:24px 0 0"><p style="font:700 10px Arial,sans-serif;letter-spacing:1.2px;color:${t.accent};margin:0 0 10px">THE TEAM ANSWER KEY</p>${riddles.map(r=>`<p style="font:12px/1.6 Arial,sans-serif;color:#535b50;margin:6px 0"><strong>${escapeHTML(r.team)}:</strong> ${richText(r.answer)}</p>`).join('')}</div>`:''}${s.question.trim()&&s.showAnswer&&s.answer.trim()?`<p style="font:11px/1.6 Arial,sans-serif;color:#7c8072;margin:24px 0 0"><strong>Trivia answer:</strong> ${richText(s.answer)}</p>`:''}</td></tr></table></td></tr></table></td></tr></table></body></html>`;
}
function emailText(s) { const riddles=activeRiddles(s);const sections=[...groupWins(s)].map(([team,wins])=>`${team}\n${wins.map(w=>`${w.title}\n${w.body}${normalizeMedia(w).map(m=>`\n${m.alt||'Image / GIF'}: ${safeURL(m.src)||`[Insert uploaded file: ${m.name}]`}${m.caption?`\n${m.caption}`:''}`).join('')}`).join('\n\n')}${riddles.find(r=>r.team===team)?`\n\nTeam ${riddles.find(r=>r.team===team).kind==='trivia'?'trivia':'brain teaser'}: ${riddles.find(r=>r.team===team).question}`:''}`).join('\n\n');return `${s.company} | Weekly Wins | ${dateLabel(s.date)}\n\n${s.headline}\n\n${s.intro}\n\n${sections}\n\n${s.fact?`Fun fact: ${s.fact}\n${safeURL(s.factSource)}\n\n`:''}${s.question?`Trivia: ${s.question}\n\n`:''}${gamesLink(s)?`Weekly brain break: ${gamesLink(s)}\n\n`:''}${s.closing}${s.showAnswer&&riddles.length?`\n\nTeam answer key\n${riddles.map(r=>`${r.team}: ${r.answer}`).join('\n')}`:''}${s.question&&s.showAnswer&&s.answer?`\n\nTrivia answer: ${s.answer}`:''}`; }
if(typeof module!=='undefined') module.exports={escapeHTML,safeURL,parseWins,emailHTML,normalizeDraft,newDraft,normalizeCustomTheme,applyVibeResult,groupWins,activeRiddles,emailText,hasWinContent,normalizeMedia,mediaSource,detectImageType,imageDimensions,vibeDraft,normalizeGames,gamesLink,safeGameURL};
if(typeof document!=='undefined') {
 let state;try{state=normalizeDraft(JSON.parse(localStorage.getItem(KEY)));}catch{state=newDraft(true);}
 const $=id=>document.getElementById(id); let toastTimer,proposal=null;
 function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saveStatus').textContent='Saved on this device';}catch{$('saveStatus').textContent='Not saved — download a draft';}}
 function preview(){state.sample=state.wins.some(w=>w.sample);const html=emailHTML(state);$('emailPreview').srcdoc=html;$('previewSubject').textContent=state.subject||'Weekly wins';$('previewSender').textContent=state.company||'Our team';$('winCount').textContent=`${state.wins.filter(hasWinContent).length} wins`;$('sampleTag').hidden=!state.sample;save();}
 function renderMedia(w,i){return `<details class="win-media" ${normalizeMedia(w).length?'open':''}><summary>▧ Images / GIFs${normalizeMedia(w).length?` · ${normalizeMedia(w).length}`:''}</summary><div class="media-drop" data-drop-win="${i}" tabindex="0" role="button" aria-label="Upload images or GIFs for win ${i+1}"><strong>Drop images & GIFs here</strong><span>or click to choose multiple files</span><small>Photos resized & compressed · GIF animation preserved</small></div><input type="file" data-upload-win="${i}" accept="image/png,image/jpeg,image/gif,image/webp" multiple hidden><div class="media-url"><input type="url" id="mediaURL${i}" aria-label="Image or GIF link for win ${i+1}" placeholder="Or paste a direct HTTPS image link"><button type="button" class="small-button" data-add-media="${i}">Add link</button></div><p class="hint">Up to 12 images per win. 2 MB total uploads per edition. For Gmail, use hosted links or download and insert uploaded files in Gmail.</p><div class="media-list">${normalizeMedia(w).map((m,j)=>`<div class="media-item"><img src="${escapeHTML(m.src)}" alt="${escapeHTML(m.alt||'Win image')}" loading="lazy"><div class="media-meta"><small>${escapeHTML(m.info||'Hosted image / GIF')}</small><label>Description<input aria-label="Description for image ${j+1} in win ${i+1}" data-win="${i}" data-media="${j}" data-media-field="alt" value="${escapeHTML(m.alt)}" placeholder="Describe this image"></label><label>Caption (optional)<input aria-label="Caption for image ${j+1} in win ${i+1}" data-win="${i}" data-media="${j}" data-media-field="caption" value="${escapeHTML(m.caption)}"></label><div class="media-actions">${m.src.startsWith('data:')?`<a href="${escapeHTML(m.src)}" download="${escapeHTML(m.name)}">Download</a>`:''}<button class="text-button" data-move-media="${i}:${j}:-1" ${j===0?'disabled':''} aria-label="Move image ${j+1} up in win ${i+1}">↑</button><button class="text-button" data-move-media="${i}:${j}:1" ${j===w.media.length-1?'disabled':''} aria-label="Move image ${j+1} down in win ${i+1}">↓</button><button class="text-button" data-remove-media="${i}:${j}">Remove</button></div></div></div>`).join('')}</div></details>`;}
 function renderCards(){ $('winCards').innerHTML=state.wins.map((w,i)=>{w.media=normalizeMedia(w);return `<div class="win-card"><div class="win-top"><label>Team<input data-i="${i}" data-field="team" aria-label="Team for win ${i+1}" value="${escapeHTML(w.team)}"></label><button class="remove-win" data-remove="${i}" aria-label="Remove win ${i+1}">×</button></div><label>Win headline <span style="font-weight:400;color:#959b8a">(optional)</span><input data-i="${i}" data-field="title" value="${escapeHTML(w.title)}" placeholder="What’s worth celebrating?"></label><label>The good stuff<textarea data-i="${i}" data-field="body" rows="3" placeholder="Share what happened and give people credit…">${escapeHTML(w.body)}</textarea></label>${renderMedia(w,i)}</div>`;}).join(''); }
 function readDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Couldn’t read this file.'));r.readAsDataURL(blob);});}
 async function optimizeImage(file){if(file.size>20*1024*1024)throw new Error('Choose a file under 20 MB.');const type=detectImageType(new Uint8Array(await file.slice(0,12).arrayBuffer()));if(!type)throw new Error('Use a PNG, JPG, GIF, or WebP image.');const original=new Blob([file],{type});let blob=original,info=`Original animation preserved · ${Math.max(1,Math.ceil(file.size/1024))} KB`;let name=file.name;
  // GIFs and potentially animated WebP files retain their original frames.
  if(type==='image/gif'||type==='image/webp'){if(file.size>MAX_UPLOAD_BYTES)throw new Error('This animation is over 2 MB. Use a smaller GIF/WebP or a hosted link.');}
  else{const bitmap=await createImageBitmap(original,{imageOrientation:'from-image'});try{const size=imageDimensions(bitmap.width,bitmap.height);const canvas=document.createElement('canvas');canvas.width=size.width;canvas.height=size.height;const context=canvas.getContext('2d');context.drawImage(bitmap,0,0,size.width,size.height);let transparent=false;if(type==='image/png'){const pixels=context.getImageData(0,0,size.width,size.height).data;for(let n=3;n<pixels.length;n+=4)if(pixels[n]<255){transparent=true;break;}}const outputType=transparent?'image/png':'image/jpeg';const compressed=await new Promise(resolve=>canvas.toBlob(resolve,outputType,.8));if(!compressed)throw new Error('Couldn’t resize this image.');if(compressed.size<file.size||size.width!==bitmap.width||size.height!==bitmap.height)blob=compressed;info=`${size.width} × ${size.height} · ${Math.ceil(blob.size/1024)} KB${blob.size<file.size?` · ${Math.round((1-blob.size/file.size)*100)}% smaller`:''}`;name=file.name.replace(/\.[^.]+$/,'')+(blob.type==='image/jpeg'?'.jpg':'.png');}finally{bitmap.close();}}
  if(blob.size>MAX_UPLOAD_BYTES)throw new Error('This image is still over 2 MB. Try a smaller image or a hosted link.');return {src:await readDataURL(blob),alt:'',caption:'',name,info};}
 async function addFiles(i,files){const w=state.wins[i];if(!w)return;const items=Array.from(files);if(!items.length)return;toast('Preparing your images…');let added=0;const errors=[];for(const file of items){try{if(!state.wins.includes(w))break;if(w.media.length>=MAX_MEDIA)throw new Error('This win already has 12 images.');const media=await optimizeImage(file);if(!state.wins.includes(w))break;const bytes=state.wins.flatMap(normalizeMedia).reduce((n,m)=>n+(m.src.startsWith('data:')?m.src.split(',')[1].length*.75:0),0);if(bytes+media.src.split(',')[1].length*.75>MAX_UPLOAD_BYTES)throw new Error('Uploads exceed 2 MB for this edition. Use hosted links for more images.');if(w.media.length>=MAX_MEDIA)throw new Error('This win already has 12 images.');w.media.push(media);added++;}catch(error){errors.push(`${file.name}: ${error.message}`);}}renderCards();preview();toast(`${added?`Added ${added} image${added===1?'':'s'}. `:''}${errors.join(' ')||'Ready to celebrate.'}`);}
 function renderThemes(){ const choices={...THEMES};if(state.customTheme)choices.custom=state.customTheme;$('themes').innerHTML=Object.entries(choices).map(([id,t])=>`<button class="theme-choice" data-theme="${id}" aria-pressed="${state.theme===id}"><span class="theme-emoji">${escapeHTML(t.emoji)}</span><strong>${escapeHTML(t.name)}</strong><small>${escapeHTML(t.note)}</small><span class="swatches"><i style="background:${t.dark}"></i><i style="background:${t.accent}"></i><i style="background:${t.light}"></i></span></button>`).join(''); }
 function renderTeamRiddles(){const riddles=state.teamRiddles||[];$('teamRiddleEditor').hidden=!riddles.length;$('teamRiddleCards').innerHTML=riddles.map((r,i)=>`<div class="win-card"><div class="section-line" style="margin:0 0 12px"><strong>${escapeHTML(r.team)}</strong><button class="remove-win" data-remove-riddle="${i}" aria-label="Remove ${escapeHTML(r.team)} ${r.kind==='trivia'?'trivia':'riddle'}">×</button></div><label>${escapeHTML(r.team)} ${r.kind==='trivia'?'trivia':'riddle'}<textarea rows="2" data-riddle="${i}" data-field="question">${escapeHTML(r.question)}</textarea></label><label>${escapeHTML(r.team)} answer<input data-riddle="${i}" data-field="answer" value="${escapeHTML(r.answer)}"></label></div>`).join('');}
 function renderGames(){state.gameThemes=normalizeGameThemes(state.gameThemes);$('wordTheme').value=state.gameThemes.word;state.gameThemes.connections.forEach((t,i)=>$('connectionTheme'+i).value=t);const p=normalizeGames(state.games);$('gameWord').value=p?.word||'';$('gameHint').value=p?.hint||'';$('gameTitle').value=p?.title||'The weekly brain break';$('gameGroups').value=p?PuzzleCore.groupsText(p):'';$('gamesURL').value=state.gamesURL||'';for(const id of ['previewGames','exportGames','removeGames'])$(id).disabled=!p;$('gamesStatus').textContent=p?`${p.date} · Ready to review. ${gamesLink(state)?'Published link added. Verify it before sending.':'Preview locally, then export and publish to add a play link.'}`:'Generate a pair of puzzles, then review or edit their answers before publishing.';}
 function readGames(){return PuzzleCore.validatePuzzle({date:state.date||localDate(),title:$('gameTitle').value,word:$('gameWord').value,hint:$('gameHint').value,groups:PuzzleCore.parseGroups($('gameGroups').value)});}
 $('randomGames').addEventListener('click',()=>{state.games=PuzzleCore.generate(state.date||localDate(),Date.now());state.gamesURL='';renderGames();preview();toast('Two puzzles ready. Review the word and Connections categories below.');});
 function gameGenerationSnapshot(){return JSON.stringify({themes:state.gameThemes,date:state.date,games:state.games,url:state.gamesURL,fields:['gameTitle','gameWord','gameHint','gameGroups'].map(id=>$(id).value)});}
 for(const id of ['wordTheme','connectionTheme0','connectionTheme1','connectionTheme2','connectionTheme3'])$(id).addEventListener('input',()=>{state.gameThemes={word:$('wordTheme').value,connections:[0,1,2,3].map(i=>$('connectionTheme'+i).value)};save();});
 $('generateGames').addEventListener('click',async()=>{
  const themes=normalizeGameThemes(state.gameThemes);if(!themes.word.trim()||themes.connections.some(t=>!t.trim()))return toast('Enter a word theme and all four Connections themes first.');
  const source=gameGenerationSnapshot(),button=$('generateGames');button.disabled=true;$('randomGames').disabled=true;button.textContent='Building your puzzles…';$('gamesStatus').classList.remove('error');$('gamesStatus').textContent='Generating a five-letter word and four Connections groups…';
  try{const r=await fetch('/api/games',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({date:state.date||localDate(),wordTheme:themes.word,connectionsThemes:themes.connections}),signal:AbortSignal.timeout(70000)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Puzzle generation failed.');if(source!==gameGenerationSnapshot())throw new Error('Your puzzle settings changed while generating. Generate again to use your latest edits.');const p=PuzzleCore.validatePuzzle(data);state.games=p;state.gamesURL='';renderGames();preview();$('gamesStatus').textContent='Themed puzzles ready. Review the answers and categories below before publishing.';toast('Themed puzzles generated. Review all four groups before publishing.');}
  catch(error){$('gamesStatus').classList.add('error');$('gamesStatus').textContent=error.name==='TimeoutError'?'Generation took too long. Try again.':error.message||'Couldn’t generate themed puzzles.';}
  finally{button.disabled=false;$('randomGames').disabled=false;button.textContent='Generate themed puzzles ✦';}
 });
 $('updateGames').addEventListener('click',()=>{try{const p=readGames();if(p.id!==state.games?.id)state.gamesURL='';state.games=p;renderGames();preview();toast('Puzzles updated. Export this edition again if you changed its answers.');}catch(error){toast(error.message);}});
 $('previewGames').addEventListener('click',()=>{if(state.games)window.open('/games/#'+encodeURIComponent(JSON.stringify(state.games)),'_blank','noopener');});
 $('exportGames').addEventListener('click',()=>{if(state.games)download(JSON.stringify(state.games,null,2),'application/json',`${state.games.id}.json`);});
 $('removeGames').addEventListener('click',()=>{state.games=null;state.gamesURL='';renderGames();preview();});
 $('gamesURL').addEventListener('input',()=>{state.gamesURL=$('gamesURL').value;preview();$('gamesStatus').textContent=gamesLink(state)?'Link added. Open it to verify the published edition before sending.':'Add a published HTTPS or S3 website game URL to include the game card in Gmail.';});
 function render(){ for(const k of ['company','date','subject','intro','headline','closing','image','imageAlt','fact','factSource','question','answer'])$(k).value=state[k];$('showAnswer').checked=state.showAnswer;renderCards();renderThemes();renderTeamRiddles();renderGames();preview(); }
 for(const k of ['company','date','subject','intro','headline','closing','image','imageAlt','fact','factSource','question','answer'])$(k).addEventListener('input',e=>{state[k]=e.target.value;preview();});
 $('showAnswer').addEventListener('change',e=>{state.showAnswer=e.target.checked;preview();});
 $('teamRiddleCards').addEventListener('input',e=>{const i=e.target.dataset.riddle,k=e.target.dataset.field;if(i!==undefined&&['question','answer'].includes(k)){state.teamRiddles[Number(i)][k]=e.target.value;preview();}});
 $('teamRiddleCards').addEventListener('click',e=>{const b=e.target.closest('[data-remove-riddle]');if(b){state.teamRiddles.splice(Number(b.dataset.removeRiddle),1);renderTeamRiddles();preview();}});
 document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===b));for(const name of ['wins','theme','extras'])$(name+'Panel').hidden=name!==b.dataset.tab;}));
 $('winCards').addEventListener('input',e=>{const d=e.target.dataset;if(d.mediaField){state.wins[Number(d.win)].media[Number(d.media)][d.mediaField]=e.target.value;preview();return;}if(d.i!==undefined&&d.field){state.wins[Number(d.i)][d.field]=e.target.value;preview();}});
 $('winCards').addEventListener('click',e=>{const drop=e.target.closest('[data-drop-win]');if(drop){$('winCards').querySelector(`[data-upload-win="${drop.dataset.dropWin}"]`).click();return;}const add=e.target.closest('[data-add-media]');if(add){const i=Number(add.dataset.addMedia),src=safeURL($('mediaURL'+i).value);if(!src)return toast('Use a direct HTTPS image or GIF link.');if(state.wins[i].media.length>=MAX_MEDIA)return toast('Up to 12 images per win.');state.wins[i].media.push({src,alt:'',caption:'',name:'image',info:''});renderCards();preview();return;}const media=e.target.closest('[data-remove-media]');if(media){const [i,j]=media.dataset.removeMedia.split(':').map(Number);state.wins[i].media.splice(j,1);renderCards();preview();return;}const move=e.target.closest('[data-move-media]');if(move){const [i,j,delta]=move.dataset.moveMedia.split(':').map(Number),items=state.wins[i].media;if(j+delta>=0&&j+delta<items.length)[items[j],items[j+delta]]=[items[j+delta],items[j]];renderCards();preview();return;}const b=e.target.closest('[data-remove]');if(b){state.wins.splice(Number(b.dataset.remove),1);renderCards();preview();}});
 $('winCards').addEventListener('keydown',e=>{const drop=e.target.closest('[data-drop-win]');if(drop&&['Enter',' '].includes(e.key)){e.preventDefault();drop.click();}});
 $('winCards').addEventListener('change',e=>{if(e.target.dataset.uploadWin!==undefined){addFiles(Number(e.target.dataset.uploadWin),e.target.files);e.target.value='';}});
 $('winCards').addEventListener('dragover',e=>{const drop=e.target.closest('[data-drop-win]');if(drop){e.preventDefault();e.dataTransfer.dropEffect='copy';drop.classList.add('dragging');}});
 $('winCards').addEventListener('dragleave',e=>{const drop=e.target.closest('[data-drop-win]');if(drop&&!drop.contains(e.relatedTarget))drop.classList.remove('dragging');});
 $('winCards').addEventListener('drop',e=>{const drop=e.target.closest('[data-drop-win]');if(drop){e.preventDefault();drop.classList.remove('dragging');addFiles(Number(drop.dataset.dropWin),e.dataTransfer.files);}});
 $('addWin').addEventListener('click',()=>{state.wins.push({team:'',title:'',body:''});renderCards();preview();$('winCards').lastElementChild.querySelector('input').focus();});
 $('parseBatch').addEventListener('click',()=>{const wins=parseWins($('batch').value);if(!wins.length)return toast('Paste a few wins first.');state.wins.push(...wins);$('batch').value='';renderCards();preview();toast(`Added ${wins.length} wins. Review the team names and wording below.`);});
 $('clearDemo').addEventListener('click',()=>{if(!state.sample)return toast('The sample wins have already been cleared.');state.wins=state.wins.filter(w=>!w.sample);state.sample=false;renderCards();preview();toast('Sample wins cleared. Ready for your team’s good news.');});
 $('themes').addEventListener('click',e=>{const b=e.target.closest('[data-theme]');if(!b)return;const old=getTheme(state),next=b.dataset.theme==='custom'?state.customTheme:THEMES[b.dataset.theme];for(const k of ['headline','intro','closing'])if(state[k]===old[k])state[k]=next[k];state.theme=b.dataset.theme;render();});
 $('desktop').addEventListener('click',()=>{$('emailContainer').classList.remove('mobile');$('desktop').setAttribute('aria-pressed','true');$('mobile').setAttribute('aria-pressed','false');});
 $('mobile').addEventListener('click',()=>{$('emailContainer').classList.add('mobile');$('desktop').setAttribute('aria-pressed','false');$('mobile').setAttribute('aria-pressed','true');});
 function download(content,type,name){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 $('download').addEventListener('click',()=>{download(emailHTML(state),'text/html',`weekly-wins-${state.date||localDate()}.html`);toast('HTML downloaded. Open it in a browser to copy the formatted email.');});
 $('backup').addEventListener('click',()=>download(JSON.stringify(state,null,2),'application/json',`weekly-wins-draft-${state.date||localDate()}.json`));
 $('importFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>12000000)throw new Error();const candidate=normalizeDraft(JSON.parse(await f.text()));if(!confirm('Replace the current edition with this saved draft?'))return;state=candidate;render();toast('Saved draft loaded.');}catch{toast('That file isn’t a supported weekly wins draft.');}finally{e.target.value='';}});
 $('copySubject').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.subject);toast('Subject copied.');}catch{toast('Clipboard unavailable. Copy the subject from the editor.');}});
 $('copyEmail').addEventListener('click',async()=>{if(state.sample&&!confirm('This email still contains sample content. Copy it anyway?'))return;try{const html=emailHTML(state,true),text=emailText(state);if(navigator.clipboard?.write&&typeof ClipboardItem!=='undefined')await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([html],{type:'text/html'}),'text/plain':new Blob([text],{type:'text/plain'})})]);else{const el=document.createElement('div');el.innerHTML=html;el.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(el);const range=document.createRange();range.selectNodeContents(el);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);const ok=document.execCommand('copy');selection.removeAllRanges();el.remove();if(!ok)throw new Error();}toast(state.wins.some(w=>normalizeMedia(w).some(m=>m.src.startsWith('data:')))?'Email copied. Download your uploaded images and insert them at the marked spots in Gmail.':'Formatted email copied! Paste into Gmail’s message body.');}catch{toast('Couldn’t copy rich text here. Download the HTML, open it, and copy from your browser.');}});
 $('reset').addEventListener('click',()=>{if(!confirm('Start a fresh edition? Download your current draft first if you want to keep it.'))return;const company=state.company;state=newDraft(false);state.company=company;render();toast('A fresh week, a fresh edition.');});
 async function checkAI(){
  $('aiStatus').classList.remove('error');$('aiStatus').textContent='Checking OpenAI connection…';
  try{const r=await fetch('/api/status',{signal:AbortSignal.timeout(5000)});if(!r.ok)throw new Error();const c=await r.json();if(typeof c.configured!=='boolean')throw new Error();$('aiStatus').textContent=c.configured?`OpenAI key configured · ${c.model}`:'Add OPENAI_API_KEY to .env. Save the file, then generate — no restart needed.';}
  catch{$('aiStatus').textContent='AI needs the local app server. Run npm start in the project folder.';$('aiStatus').classList.add('error');}
 }
 $('refreshAI').addEventListener('click',checkAI);
 document.querySelectorAll('[data-prompt]').forEach(b=>b.addEventListener('click',()=>{$('vibePrompt').value=b.dataset.prompt;}));
 for(const [selected,other] of [['includeRiddle','includeTrivia'],['includeTrivia','includeRiddle']])$(selected).addEventListener('change',()=>{if($(selected).checked)$(other).checked=false;proposal=null;$('vibeReview').hidden=true;});
 $('generateVibe').addEventListener('click',async()=>{
  const prompt=$('vibePrompt').value.trim();if(!prompt){$('vibePrompt').focus();return toast('Describe the vibe you want first.');}
  const source=JSON.stringify(state),draft=JSON.parse(source),includeRiddle=$('includeRiddle').checked,includeTrivia=$('includeTrivia').checked;
  $('generateVibe').disabled=true;$('generateVibe').textContent='Dreaming it up…';$('aiStatus').classList.remove('error');$('aiStatus').textContent='Generating a look and copy for your edition…';proposal=null;$('vibeReview').hidden=true;
  try{
   const r=await fetch('/api/vibe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,draft:vibeDraft(draft),includeRiddle,includeTrivia}),signal:AbortSignal.timeout(70000)});
   let result;try{result=await r.json();}catch{throw new Error('AI needs the local app server. Run npm start in the project folder.');}
   if(!r.ok)throw new Error(result.error||'Couldn’t generate a vibe. Try again.');
   if(source!==JSON.stringify(state))throw new Error('Your edition changed while the vibe was generating. Generate again to use your latest wins.');
   if(includeRiddle!==$('includeRiddle').checked||includeTrivia!==$('includeTrivia').checked)throw new Error('Your question option changed. Generate again to use your latest choice.');
   const candidate=applyVibeResult(draft,result,includeRiddle,includeTrivia);proposal={source,candidate};
   $('generatedName').textContent=result.theme.name;$('generatedNote').textContent=result.theme.note;
   $('imageIdea').textContent=result.imageIdea?`Image / GIF idea: ${result.imageIdea}`:'';$('vibeReview').hidden=false;
   // WebKit can load a srcdoc frame with zero layout while its parent is hidden.
   // Mount a fresh frame only after revealing the review, so it lays out normally.
   const frame=document.createElement('iframe');frame.id='vibePreview';frame.title='Proposed AI vibe email';frame.setAttribute('sandbox','');frame.srcdoc=emailHTML(candidate);$('vibePreview').replaceWith(frame);
   $('aiStatus').textContent='Your proposal is ready below. Your current email stays as it is until you choose Use this vibe.';toast('Your new vibe is ready to review.');
  }catch(error){$('aiStatus').classList.add('error');$('aiStatus').textContent=error.name==='TimeoutError'?'Generation took too long. Try again.':error.message||'Couldn’t generate a vibe. Try again.';}
  finally{$('generateVibe').disabled=false;$('generateVibe').textContent='Generate vibe ✦';}
 });
 $('applyVibe').addEventListener('click',()=>{if(!proposal)return;if(proposal.source!==JSON.stringify(state)){proposal=null;$('vibeReview').hidden=true;return toast('Your edition changed. Generate again to include your latest edits.');}state=proposal.candidate;proposal=null;$('vibeReview').hidden=true;render();toast('Your new vibe is applied. Review the live email before copying into Gmail.');});
 $('discardVibe').addEventListener('click',()=>{proposal=null;$('vibeReview').hidden=true;$('aiStatus').textContent='Proposal discarded. Your current edition is unchanged.';});
 render();checkAI();
}
